 if(p.fitSinglePage){const full={...p,standardText:window.SOP_IMPORT?.active(p)?'':(A.layout==='wide-v2'?'':project.settings.standardText||'')};let lo=.01,hi=1,fitScale=1;if(heightOf({...full,fitScale:1,importedPreviewScale:1})>OP_CAP){for(let i=0;i<15;i++){const mid=(lo+hi)/2;if(heightOf({...full,fitScale:mid,importedPreviewScale:mid})<=OP_CAP)lo=mid;else hi=mid;}fitScale=lo;}const count=Math.max(1,Math.ceil(p.materials.length/MAT_ROWS),Math.ceil(p.checks.length/2));return Array.from({length:count},(_,i)=>({...full,...(i?{steps:'',requirements:'',photos:[],importedContent:null,canvas:null,standardText:''}:{}),fitScale:i?1:fitScale,importedPreviewScale:i?1:fitScale,materials:p.materials.slice(i*MAT_ROWS,i*MAT_ROWS+MAT_ROWS),checks:p.checks.slice(i*2,i*2+2),sourceId:p.id,fragment:i,id:p.id+':'+i}));}
 if(window.SOP_IMPORT?.active(p)){let importedPreviewScale=1;if(heightOf({...p,importedPreviewScale:1})>OP_CAP){let lo=.25,hi=1;for(let i=0;i<12;i++){const mid=(lo+hi)/2;if(heightOf({...p,importedPreviewScale:mid})<=OP_CAP)lo=mid;else hi=mid;}importedPreviewScale=lo;}return [{...p,importedPreviewScale,sourceId:p.id,fragment:0,id:p.id+':0',standardText:''}];}
 const blocks=[];for(const s of p.steps.split('\n').filter(x=>x.trim()))blocks.push({type:'steps',value:s});
 // A page keeps at most two photos at legible size. Further photos get continuation pages.
 for(let i=0;i<p.photos.length;i+=2)blocks.push({type:'photos',value:p.photos.slice(i,i+2)});
 for(const s of p.requirements.split('\n').filter(x=>x.trim()))blocks.push({type:'requirements',value:s});
