function operationPaper(p){if(A.layout==='wide-v2')return window.SOP_TEMPLATE.operationPaper(p,project,opHtml(p));const m=project.meta;const mats=[...p.materials];while(mats.length<4)mats.push({});const checks=[...p.checks];while(checks.length<2)checks.push({});const sign=(name)=>esc(name)+(m.date?'<br>'+esc(m.date):'');return paperChrome(`<div class="doc-head"><div>${logoHtml()}</div><div>${esc(metadataTitle())}</div><div class="doc-fields"><div><b>工艺文件编号</b><span>${esc(m.number)}</span></div><div><b>工序作业名称</b><span>${esc(p.name)}${p.isContinuation?'（续）':''}</span></div></div><div class="doc-pages"><div>共 ${p.total} 页</div><div>第 ${p.pageNo} 页</div></div></div><div class="doc-labels"><div>工序号</div><div>工位号</div><div>工序作业内容</div><div>工装、工具、设备</div></div><div class="doc-body"><div class="doc-vertical"><div class="station-number">${esc(window.SOP_IMPORT?.active(p)&&p.processLabel?p.processLabel:String(p.processNo).padStart(2,'0'))}</div><div class="station-foot"><div>工时</div><div>${esc(p.duration)}</div></div></div><div class="doc-vertical"><div class="station-number">${esc(p.station)}</div><div class="station-foot"><div>人力</div><div>${esc(p.people)}</div></div></div><div class="op-cell">${opHtml(p)}</div><div class="doc-right"><table class="doc-table materials"><colgroup><col style="width:10%"><col style="width:39%"><col style="width:34%"><col style="width:17%"></colgroup><tr><th>序号</th><th>编码＋名称</th><th>图号或规格</th><th>备注</th></tr>${mats.map((r,i)=>`<tr><td>${r.name?i+1:''}</td><td>${esc(r.name)}</td><td>${esc(r.spec)}</td><td>${esc(r.qty)}</td></tr>`).join('')}</table><table class="doc-table checks"><tr><th>序号</th><th>控制特性</th><th>技术要求</th><th>生产自检</th><th>质量抽检</th><th>重要度</th><th>管理手段</th></tr>${checks.map((r,i)=>`<tr><td>${r.feature?i+1:''}</td><td>${esc(r.feature)}</td><td>${esc(r.standard)}</td><td>${esc(r.self)}</td><td>${esc(r.audit)}</td><td>${esc(r.importance)}</td><td>${esc(r.method)}</td></tr>`).join('')}</table><div class="doc-notes">备注：${esc(p.notes)}</div><div class="doc-legend">${esc(project.settings.importance)}</div><div class="doc-legend">${esc(project.settings.management)}</div></div></div><div class="doc-sign"><div class="revision-box"><span>序号</span><span>标记</span><span>处数</span><span>更改文件号</span><span>签字（日期）</span></div><div><table class="sign-table"><tr><td>编制（日期）</td><td>审核（日期）</td><td>批准（日期）</td><td>版本号</td></tr><tr><td>${sign(m.author)}</td><td>${sign(m.reviewer)}</td><td>${sign(m.approver)}</td><td>${esc(m.version)}</td></tr></table></div></div>`);}
