function mountPaper(host,html,width){host.innerHTML='<div class="page-frame">'+html+'</div>';const frame=host.firstElementChild,paper=frame.firstElementChild;const scale=Math.min(1,width/1122.52);paper.style.transform=`scale(${scale})`;frame.style.width=(1122.52*scale)+'px';frame.style.height=(793.7*scale)+'px';}

const frontNames={cover:'封面',history:'修改履历',flow:'工艺流程图'};
