function renderPhotos(){const p=page(),g=$('#photoGrid');g.innerHTML='';p.photos.forEach(ph=>{const el=document.createElement('div');el.className='photo-card';el.innerHTML=`<img src="${esc(ph.rendered||ph.data)}" alt="${esc(ph.caption||'作业图片')}" data-edit-photo="${ph.id}"><div class="photo-controls"><input aria-label="图片说明" value="${esc(ph.caption)}" data-caption="${ph.id}"${p.fixed.includes('photos')?' readonly':''}><div class="row">${p.fixed.includes('photos')?'<span class="fixed-badge">固定沿用</span>':`<button data-edit-photo="${ph.id}">标注 / 裁剪</button><button data-replace-photo="${ph.id}">更换</button><button data-remove-photo="${ph.id}" aria-label="删除图片">×</button>`}</div></div>`;g.append(el);});if(!p.photos.length)g.innerHTML='<div class="upload-area photo-empty">添加现场照片或粘贴截图</div>';if(g.querySelector('.upload-area'))g.querySelector('.upload-area').onclick=()=>$('#photoFile').click();$$('[data-edit-photo]').forEach(el=>el.onclick=()=>{if(!p.fixed.includes('photos'))openPhoto(el.dataset.editPhoto);});$$('[data-caption]').forEach(el=>bindInput(el,v=>{const ph=p.photos.find(x=>x.id===el.dataset.caption);ph.caption=v;}));$$('[data-remove-photo]').forEach(el=>el.onclick=()=>{snapshot();p.photos=p.photos.filter(x=>x.id!==el.dataset.removePhoto);renderPhotos();changed();});$$('[data-replace-photo]').forEach(el=>el.onclick=()=>{replacePhotoId=el.dataset.replacePhoto;$('#replaceFile').click();});}
async function filePhoto(file){if(file.size>35*1024*1024)throw Error('单张图片请控制在 35MB 以内。');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('读取图片失败'));r.readAsDataURL(file);});const im=await loadImage(data);const scale=Math.min(1,1800/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);return {id:uid(),data:c.toDataURL('image/jpeg',.88),caption:file.name.replace(/\.[^.]+$/,''),width:c.width,height:c.height,marks:[]};}
async function addPhotos(files){const p=page();if(!p)return toast('请先新增一道工序。');if(p.fixed.includes('photos'))return toast('请先解锁固定配图。');snapshot();try{for(const f of files){if(f.type.startsWith('image/'))p.photos.push(await filePhoto(f));}renderEditor();changed();refresh();toast('照片已加入工序，页码已重新计算。');}catch(e){toast(e.message,true);}}
async function prepareImages(candidate=project){if(!candidate.nativeWord&&candidate.frontContent?.flowManual&&!candidate.frontContent?.flowGraph){const c=candidate.frontContent||{},source=c.flowManual?String(c.flowText||'').split('\n').filter(Boolean).map((name,i)=>({name,processId:String(i)})):candidate.pages;if(source.length<=24)candidate.frontContent={...c,flowGraph:window.SOP_OBJECTS.fromProcesses(source),flowMode:'editable'};}if(window.SOP_WORD?.ensureOriginalFront)await window.SOP_WORD.ensureOriginalFront(candidate);for(const p of candidate.pages)for(const ph of p.photos){if(!ph.width||!ph.height){const im=await loadImage(ph.data);ph.width=im.naturalWidth;ph.height=im.naturalHeight;}ph.rendered=await annotated(ph);}}
function showForm(title,html,apply){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;$('#dialogApply').hidden=!apply;$('#dialogApply').textContent='保存';$('#dialogApply').onclick=()=>{try{apply?.();$('#formDialog').close();}catch(e){toast(e.message,true);}};$('#formDialog').showModal();}
function editMetadata(){const fields=[['product','产品型号'],['title','文件名称'],['number','文件编号'],['version','版本'],['bare','裸机成品料号'],['packed','包装成品料号'],['date','生效日期'],['author','制定 / 编制'],['reviewer','审核'],['approver','批准'],['qualitySigner','质量会签'],['productionSigner','生产会签']];showForm('文档信息',`<div class="notice">这些信息只填写一次，所有页面同步更新。公司名称和 Logo 可在“固定格式”中修改。</div><div class="form-grid">${fields.map(([k,l])=>`<label><span>${l}</span><input data-docmeta="${k}" type="${k==='date'?'date':'text'}" value="${esc(project.meta[k])}"></label>`).join('')}</div><div class="section-gap"><div class="field-top"><strong>本次修改履历</strong></div><input id="historySummary" placeholder="可选：填写本次修改内容，保存后加入修改履历"></div>`,()=>{snapshot();$$('[data-docmeta]').forEach(el=>project.meta[el.dataset.docmeta]=el.value);const summary=$('#historySummary').value.trim();if(summary){if(project.history.length>=15)throw Error('当前修改履历页最多 15 条，请先在项目中归档旧记录。');project.history.push({date:project.meta.date||new Date().toLocaleDateString('sv-SE'),number:project.meta.number,version:project.meta.version,summary,author:project.meta.author,reviewer:project.meta.reviewer,approver:project.meta.approver});}changed();refresh();});}
function editSettings(){const s=project.settings;let pendingLogo=s.logo||'';
 showForm('固定格式与沿用内容',`<div class="notice">公司信息与 Logo 会同步用于封面、预览和导出。设置随当前 SOP 保存，新建时继续沿用。</div><div class="form-grid"><label class="wide"><span>公司名称</span><input data-setting="company" maxlength="100" value="${esc(s.company)}"></label><div class="wide logo-setting"><span>公司 Logo</span><div class="logo-preview"><img id="settingsLogo" alt="Logo 预览" ${pendingLogo?'src="'+esc(pendingLogo)+'"':'hidden'}><span id="logoEmpty" ${pendingLogo?'hidden':''}>尚未设置 Logo</span></div><div class="row"><button type="button" id="chooseLogo">上传 / 更换 Logo</button><button type="button" id="removeLogo">移除 Logo</button></div><input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><small>PNG、JPEG 或 WebP，支持透明背景；保持原比例放入原版式。</small></div><label class="check wide"><input type="checkbox" data-setting="showLogo" ${s.showLogo!==false?'checked':''}><span>在 SOP 中显示 Logo</span></label><label class="wide"><span>保密等级</span><select data-setting="confidentialLevel"><option value="" disabled ${!window.SOP_IMPORT.confidentialityLevel(s)?'selected':''}>请选择保密等级</option>${['绝密','机密','一般'].map(level=>`<option value="${level}" ${window.SOP_IMPORT.confidentialityLevel(s)===level?'selected':''}>${level}</option>`).join('')}</select><small>单选后自动生成 SOP 页眉中的保密等级文字。</small></label><label class="wide"><span>页脚版权声明</span><textarea data-setting="copyright" rows="2">${esc(s.copyright)}</textarea></label><label class="check"><input type="checkbox" data-setting="cover" ${s.cover?'checked':''}><span>包含封面</span></label><label class="check"><input type="checkbox" data-setting="history" ${s.history?'checked':''}><span>包含修改履历</span></label><label class="check"><input type="checkbox" data-setting="flow" ${s.flow?'checked':''}><span>包含顺序流程图</span></label><label><span>正文页码统计规则</span><select data-setting="numbering"><option value="body" ${s.numbering==='body'?'selected':''}>仅工序页计数（其他页面不计入）</option></select></label></div>`,()=>{

  snapshot();$$('[data-setting]').forEach(el=>s[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value);if(s.confidentialLevel)s.confidential=window.SOP_IMPORT.confidentialityText(s);s.logo=pendingLogo;changed();refresh();
 });
 const updateLogo=()=>{$('#settingsLogo').hidden=!pendingLogo;if(pendingLogo)$('#settingsLogo').src=pendingLogo;else $('#settingsLogo').removeAttribute('src');$('#logoEmpty').hidden=!!pendingLogo;};
 $('#chooseLogo').onclick=()=>$('#logoFile').click();$('#removeLogo').onclick=()=>{pendingLogo='';updateLogo();};
 $('#logoFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;const apply=$('#dialogApply');apply.disabled=true;try{if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>10*1024*1024)throw Error('请选择 10MB 以内的 PNG、JPEG 或 WebP 图片。');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Logo 读取失败'));r.readAsDataURL(f);}),im=await loadImage(data);if(im.width*im.height>40000000)throw Error('Logo 分辨率过大，请缩小后上传。');const scale=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);pendingLogo=c.toDataURL('image/png');updateLogo();}catch(err){toast(err.message,true);}finally{apply.disabled=false;e.target.value='';}};
}
function addPage(continuation=false){const old=page();snapshot();const p=blankPage(continuation?old?.processId:undefined);if(old){if(continuation){p.name=old.name;p.station=old.station;p.signoff=clone(old.signoff);}for(const k of old.fixed||[])p[k]=clone(old[k]);p.fixed=[...(old.fixed||[])];const i=project.pages.indexOf(old);project.pages.splice(i+1,0,p);}else project.pages.push(p);selected=p.id;renderEditor();changed();refresh();}
function deletePage(){if(String(selected).startsWith('front:')){snapshot();project.settings[selected.split(':')[1]]=false;selected=project.pages[0]?.id;renderEditor();changed();refresh();return;}const old=page();if(!old)return;const count=layout.filter(x=>x.sourceId===old.id).length;const msg=count>1?`当前基础页及其自动续页共 ${count} 页将一起删除。可用“撤销”恢复。`:'删除当前页面及其内容？可用“撤销”恢复。';if(!confirm(msg))return;snapshot();const i=project.pages.indexOf(old);project.pages.splice(i,1);selected=project.pages[Math.min(i,project.pages.length-1)]?.id;renderEditor();changed();refresh();}
function movePage(delta){recalc();const index=selectedDocumentIndex(),to=index+delta;if(index>=0&&to>=0&&to<orderedPages().length)moveDocumentPage(index,to);}
async function showFull(scrollTo=0){await prepareImages();recalc();const host=$('#fullPreview');host.replaceChildren();const items=orderedPages().map(x=>x.kind==='body'?operationPaper(x.page):frontPaper(x.page));items.forEach(html=>{const container=document.createElement('div');host.append(container);mountPaper(container,html,Math.min(1123,Math.max(280,window.innerWidth*.92-80)));});$('#fullCount').textContent=`工序 ${layout.length} 页（参与页码）＋其他 ${front.length} 张（不计页码），文档共 ${items.length} 张。`;$('#previewDialog').showModal();if(scrollTo)host.children[scrollTo]?.scrollIntoView({block:'start'});}
async function printPdf(){const b=$('#printBtn');b.disabled=true;try{await prepareImages();recalc();$('#printRoot').innerHTML=orderedPages().map(x=>x.kind==='body'?operationPaper(x.page):frontPaper(x.page)).join('');await Promise.all([...$('#printRoot').querySelectorAll('img')].map(im=>im.decode().catch(()=>{})));await document.fonts.ready;if(window.sopDesktop){const result=await window.sopDesktop.exportPDF(filename()+'.pdf');if(result.error)throw Error(result.error);if(!result.canceled)toast('PDF 已保存。');}else{toast('在打印窗口中选择“另存为 PDF”，纸张使用 A4 横向，关闭浏览器附加页眉页脚。');setTimeout(()=>window.print(),200);}}catch(e){toast('PDF 导出失败：'+e.message,true);}finally{b.disabled=false;}}
async function flushSave(){clearTimeout(saveTimer);if(!autosaveReady)throw Error('本机恢复缓存不可用，请点击“保存”写入项目文件。');await dbWrite(clone(project));lastSaved=revision;}
